```javascript
// [...]

var facets_for_select = [{
    name: 'color',
    attribute_name: 'color_original',
    header_text: 'Couleurs',
    sort_by: ['isRefined', 'name:asc'],
    search_for_facet_values: {
      placeholder: 'Recherchez une couleur',
      no_results: 'Aucune couleur ne correspond'
    },
  },{

// [...]

  facets_for_select.forEach(function(facet_config) {
    // [...]
    try {
      search.addWidget(
        instantsearch.widgets.refinementList({
          autoHideContainer: true,
          container: '#filter-' + facet_config.name,
          attributeName: facet_config.attribute_name,
          sortBy: facet_config.sort_by ? facet_config.sort_by : ['isRefined', 'count:desc', 'name:asc'],
          limit: facet_config.limit ? facet_config.limit : 200,
          operator: 'or',
          cssClasses: cssClasses_for.filters,
          templates: {
            header: getHeader( facet_config.header_text ),
            item : facet_config.getItem ? facet_config.getItem : getItem,
          },
          searchForFacetValues: facet_config.search_for_facet_values && {
            placeholder: facet_config.search_for_facet_values.placeholder,
            templates: {
              noResults: '<div class="sffv_no-results">' +
                facet_config.search_for_facet_values.no_results +
                ' pour cette catégorie.</div>'
            }
          }
        })
      );
    } catch (e) {
      console.debug('Could not init widgets for: ' + facet_config.name)
    }
  });
